      "id": "inventory-surplus-cost-basis-natural-vs-other",
      "updatedAt": "2026-08-04",
      "topic": "存货",
      "difficulty": "高频易错",
      "question": "存货盘盈中，自然溢余和其他原因盘盈使用的成本有什么区别？",
      "summary": "自然溢余通常不把盘盈部分当作新取得存货，而是在原总成本不变的基础上调整库存数量和单位成本；其他原因盘盈通常按重置成本补确认存货，批准后按原因冲减管理费用、计入营业外收入或按差错更正处理。",
      "conclusion": [
        "自然溢余的重点是调整库存存货数量以及存货的单位成本，通常不单独确认一笔盘盈收益。",
        "其他原因导致的存货盘盈，通常按重置成本入账。",
        "属于日常收发计量且不重大的差错，批准后通常冲减管理费用。",
        "属于重大会计差错的，应按差错更正进行会计处理。",
        "如果题目明确属于非日常原因且要求计入损益，可能计入营业外收入，做题时以题目原因和教材表述为准。"
      ],
      "reasoning": [
        "自然溢余通常是水分、重量、计量换算等自然原因导致实物数量与账面数量不一致，本质不是企业额外取得一批新存货，因此处理思路是调数量、调单位成本。",
        "例如账面数量 100 件、总成本 1,000 元、单位成本 10 元；盘点发现自然溢余为 105 件时，通常保持总成本 1,000 元不变，将单位成本调整为 1,000 / 105 = 9.52 元。",
        "其他原因盘盈更像账上漏记了一部分存货，需要把多出的存货补入账；补入账时没有原始购入成本可直接沿用，所以按重置成本等确定入账金额。",
        "批准处理时再看盘盈原因：日常收发计量且不重大，通常冲减管理费用；重大会计差错，按前期差错更正；题目明确为其他非日常原因时，按题目要求可能计入营业外收入。"
      ],
      "memory": [
        "自然溢余调单位成本，不补一笔新收益。",
        "其他盘盈按重置成本，批准处理再看原因。",
        "小差错冲管理，大差错走更正。"
      ],
      "pitfalls": [
        "不要把自然溢余也机械地按重置成本确认盘盈收益；自然溢余常见处理是调整数量和单位成本。",
        "不要只背“存货盘盈冲减管理费用”；如果题目明确是重大会计差错，应按差错更正处理。",
        "自然溢余处理的关键是总成本和单位成本口径，不是借贷方向本身。"
      ],
