      "diagram": "flowchart LR\n  A[A发行股份取得B股权] --> B{交易后谁控制A}\n  B -->|B原股东控制| C[会计上B购买A]\n  C --> D[站在B角度计算合并成本]\n  D --> E[虚拟发行B股给A原股东]\n  E --> F[虚拟发行股数乘B股公允价值]\n  F --> G[取得A原股东权益的成本]\n  C --> H[B未换股部分]\n  H --> I[少数股东权益]\n  I --> J[不改变购买A的合并成本]"
