      "question": "连续合并中，“先抵期初、再抵结转、最后抵差额”是什么意思？为什么不能机械复制上年分录？",
      "summary": "连续编制合并报表时，期初处理的对象不是上年分录文本，而是上年末仍留在期初存货中的累计差额。内部未实现利润按本年存货去向转入主营业务成本或继续冲减存货；存货跌价准备则按“期初账面准备－期初集团应有准备”的累计净差额，以年初未分配利润为对方科目滚存。",
