          "scope": "出租人；资产公允价值 100 万、初始直接费用 2 万、未来租赁收款额 110 万、未担保余值 10 万",
          "condition": "租赁投资总额 120 万，按内含利率折现的净投资为 102 万，未实现融资收益为 18 万",
