      "difficulty": "高频理解",
      "question": "投资性房地产中的“范围”“取得方式”“转换”分别在回答什么问题？“性质认定”和“建造期科目”又该怎么区分？",
      "summary": "范围解决“它算不算投资性房地产”，取得方式解决“它怎么来的、初始成本怎么算”，转换解决“它原来不是投资性房地产，后来用途变了能不能转进来”。进一步做题时，还要把“性质认定”和“建造期科目”分开：前者看它是不是投资性房地产，后者看建造成本暂时记在哪个科目。",
      "conclusion": [
        "范围问题看对象和持有目的，判断某项房地产是否属于投资性房地产。",
        "外购房地产、自行建造房地产属于取得方式，不是在范围之外新增的投资性房地产类型。",
        "自用房地产、存货等在用途改变后，可能通过转换进入或退出投资性房地产。",
        "“性质认定”回答的是这项房地产算不算投资性房地产；“建造期科目”回答的是建造中的成本暂时归集到哪里，这两个问题不能混为一谈。"
      ],
      "reasoning": [
        "同样是投资性房地产，可能是买来的，也可能是自己建的，还可能是原来属于自用房地产或存货，后来因用途改变转进来的。",
        "考试中如果把范围、取得方式、转换混在一起，就容易把‘外购型投资性房地产’误记成新的分类。",
        "处理顺序应当是先判断性质，再判断来源，最后再看是否发生用途变化。",
        "<span class=\"text-danger\">如果董事会已有正式书面决议，明确在建建筑物将用于经营出租，那么从性质上可以理解为未来用于投资性房地产；但建造期成本在教材和实务中通常仍先通过“在建工程”归集。</span>",
        "<span class=\"text-danger\">只有当原资产本来已经是投资性房地产，再发生改扩建等再开发且将来仍作为投资性房地产时，才更强调在再开发期间继续作为投资性房地产，并通过“投资性房地产——在建”核算。</span>"
      ],
      "memory": [
        "范围看它算不算，取得看它怎么来，转换看它后来变没变。",
        "出租增值定范围，外购自建定来源，用途改变看转换。",
        "董事会决议解决‘它是什么’，在建科目解决‘钱记在哪’。",
        "新建先走在建工程，已是投房再走投房在建。"
      ],
      "pitfalls": [
        "外购房地产不是投资性房地产的一种范围类型，而是投资性房地产的取得方式。",
        "自行建造房地产也不是新增一种投资性房地产，它只是形成投资性房地产的一条路径。",
        "空置建筑物、在建建筑物不是天然就是投资性房地产，仍要看是否已正式明确用于经营出租。",
        "不要因为一项在建建筑物未来用于出租，就机械地认为建造期间每笔支出都必须直接借“投资性房地产”。",
        "“投资性房地产——在建”最典型适用于原本已经属于投资性房地产、后来又进行改扩建的情形，而不是所有未来出租的在建项目。"
      ],
      "diagram": "flowchart LR\n    A[\"先判断：它算不算投资性房地产\"] --> B[\"范围\"]\n    B --> B1[\"出租\"]\n    B --> B2[\"增值\"]\n\n    A --> C[\"再判断：它怎么来的\"]\n    C --> C1[\"外购\"]\n    C --> C2[\"自行建造\"]\n\n    A --> D[\"最后判断：用途后来变没变\"]\n    D --> D1[\"自用/存货转入\"]\n    D --> D2[\"投资性房地产转出\"]\n\n    A --> E[\"再分清：建造期钱记在哪\"]\n    E --> E1[\"新建未来出租 -> 在建工程\"]\n    E --> E2[\"已是投房再改扩建 -> 投资性房地产——在建\"]",
