        "自用房地产或存货转入公允价值模式投资性房地产时，以转换日公允价值入账；高于原账面价值的差额通常计入其他综合收益，低于原账面价值的差额计入公允价值变动损益。",
        "成本模式投资性房地产转为自用房地产或存货时，按账面价值结转；公允价值模式投资性房地产转出时，以转换日公允价值作为转出后资产的账面价值，转换日公允价值与原账面价值的差额计入公允价值变动损益。"
