        "反方向特别容易混淆：公允价值模式投资性房地产转出时，不能机械地说‘按账面价值转’；应先以转换日公允价值计量，差额进入公允价值变动损益。",
        "学习转换最稳的方法不是死记分录，而是先判断‘谁转谁、转入后是什么模式、转换日看什么价值基础’。"
