      "id": "income-tax-liability-tax-base-comparison",
      "updatedAt": "2026-08-06",
      "topic": "所得税费用",
      "difficulty": "高频基础",
      "question": "负债的计税基础如何判断？",
      "summary": "负债计税基础的核心是看未来履行或结清负债时，税法还允许扣除多少。普通负债用“账面价值减未来可扣除金额”，预收收入则看未来是否还纳税；表外项目虽然没有确认资产负债，但如果未来可以结转扣除，也可能形成可抵扣暂时性差异。",
      "conclusion": [
        "负债的计税基础 = 负债账面价值 - 未来期间计算应纳税所得额时按税法规定可予扣除的金额。",
        "预收收入或合同负债的计税基础 = 账面价值 - 未来期间按税法规定非应税收入的金额。",
        "合同负债只有在收款时税法已将其计入应纳税所得额、未来会计确认收入时不再纳税的情况下，才通常形成可抵扣暂时性差异和递延所得税资产。",
        "未来能扣的负债，计税基础会变小，常形成可抵扣暂时性差异；未来永远不能扣的支出通常是永久性差异。",
        "未确认资产负债的项目，只要税法允许以后年度结转扣除，也可能形成可抵扣暂时性差异。"
      ],
      "reasoning": [
        "【普通负债】\n短期借款本金、应付账款未来偿还时通常不得税前扣除，计税基础一般等于账面价值，不产生暂时性差异。",
        "【未来可扣除负债】\n预计产品质量保证费用、暂时不得扣除而未来支付时可扣除的利息，未来会减少应纳税所得额，因此计税基础通常低于账面价值，形成可抵扣暂时性差异。",
        "【永久不得扣除】\n税收罚款、滞纳金、超标且永久不得扣除的支出，未来不能税前扣除，计税基础等于账面价值，不形成暂时性差异，只形成永久性差异。",
        "【合同负债（预收收入）】\n合同负债账面价值 100：若收款时税法已经计入应纳税所得额，未来确认会计收入时该 100 不再纳税，未来非应税收入金额为 100，计税基础 = 100 - 100 = 0；负债账面价值大于计税基础，形成可抵扣暂时性差异 100，符合条件时确认递延所得税资产。若税法也在未来履约、会计确认收入时才计税，未来非应税收入为 0，计税基础 = 100，不形成暂时性差异。",
        "【表外项目】\n超标广告费、业务宣传费、职工教育经费、公益性捐赠、可弥补亏损、税款抵减等，若未来可以扣除或抵减，即使没有资产负债表项目，也可能形成可抵扣暂时性差异。"
      ],
      "memory": [
        "普通负债看未来能不能扣：未来能扣，计税基础变小；未来不能扣，计税基础等于账面价值。",
        "合同负债看未来还纳不纳税：未来不纳税，计税基础通常为 0，形成递延所得税资产；未来还纳税，计税基础通常等于账面价值。",
        "表外项目看以后能不能结转扣：以后能扣，形成可抵扣暂时性差异；以后不能扣，就是永久性差异。"
      ],
      "pitfalls": [
        "不要把所有纳税调增都当成暂时性差异；未来不能扣的调增是永久性差异。",
        "不要忽略合同负债的特殊公式，也不要把增值税的纳税时点误当成企业所得税的纳税时点。",
        "不要因为没有确认资产或负债，就否定暂时性差异；关键看税法未来是否允许扣除或抵减。"
      ],
