        "【权益法】\n权益法下，若拟长期持有，通常不准备近期出售，差异不会通过处置转回；权益法确认的投资收益未来分回股利时很多情况下免税，因此一般不确认递延所得税影响。",
        "【一般规则】\n投资相关应纳税暂时性差异原则确认递延所得税负债，但如果投资方有决定权，且没有近期出售、清算或应税分红计划，两个条件同时满足时可以不确认。",
