      "question": "股份支付相关的当期及递延所得税如何处理？",
      "summary": "股份支付确认成本费用后，所得税处理看税法是否允许税前扣除。税法允许未来扣除时，等待期内按期末股票市价估计未来可税前扣除金额，并按已过等待期比例确认递延所得税资产；与累计费用对应的税收利益进所得税费用，超过累计费用的额外税收利益进资本公积。",
