      "updatedAt": "2026-06-09",
      "topic": "或有事项",
      "difficulty": "高频易错",
      "question": "预计负债的确认条件和或有负债的区别",
      "summary": "预计负债的确认需要同时满足三个条件：",
      "conclusion": [
        "预计负债的确认需要同时满足三个条件：",
        "```text\n1. 该义务是企业承担的现时义务；\n2. 履行该义务很可能导致经济利益流出企业；\n3. 该义务的金额能够可靠计量。\n```",
        "三个条件同时满足，才确认预计负债。",
        "如果不满足预计负债确认条件，通常不能确认负债，而应进一步判断是否属于或有负债。"
      ],
      "reasoning": [
        "【判断逻辑】\n预计负债强调的是已经达到确认条件的负债。",
        "【判断逻辑】\n它不是只要有不确定性就确认，而是要求企业已经承担现时义务，并且经济利益很可能流出，金额还能够可靠计量。",
        "【判断逻辑】\n如果只是潜在义务，或者虽然是现时义务但不满足“很可能流出”或“可靠计量”的条件，通常不能确认为预计负债。",
        "【或有负债包括什么】\n或有负债主要包括两类：",
        "【或有负债包括什么】\n1. 过去的交易或者事项形成的潜在义务，其存在须通过未来不确定事项的发生或不发生予以证实；\n2. 过去的交易或者事项形成的现时义务，但履行该义务不是很可能导致经济利益流出企业，或者该义务的金额不能可靠计量。",
        "【对比总结】\n| 情况 | 会计处理 |\n| --- | --- |\n| 现时义务、很可能流出、金额能够可靠计量 | 确认为预计负债 |\n| 潜在义务 | 属于或有负债，通常披露 |\n| 现时义务，但经济利益不是很可能流出 | 属于或有负债，通常披露 |\n| 现时义务，但金额不能可靠计量 | 属于或有负债，通常披露 |\n| 根本没有义务，或经济利益流出可能性极小 | 一般不确认，通常也不披露 |"
      ],
      "memory": [
        "```text\n三条件齐全，确认预计负债；\n少条件但有义务，考虑或有负债；\n连义务都没有，通常不处理。\n```"
      ],
      "pitfalls": [
        "不要简单记成“少任意一个条件就一定是或有负债”。",
        "更准确的说法是：",
        "```text\n少任意一个预计负债确认条件，就不能确认为预计负债；\n但是否属于或有负债，还要看是否存在潜在义务或现时义务。\n```",
        "如果根本不存在义务，就既不是预计负债，也通常不是或有负债。"
      ],
      "tags": [
        "或有事项",
        "预计负债",
        "或有负债"
      ]
