        "【哪些事项属于重组】\n| 重组事项 | 理解 |\n| --- | --- |\n| 出售或终止企业的部分业务 | 例如出售某条业务线、停止某类产品经营 |\n| 对企业组织结构进行较大调整 | 例如大规模部门合并、裁撤、管理层级调整 |\n| 关闭企业的部分营业场所，或将营业活动由一个国家或地区迁移到其他国家或地区 | 例如关闭门店、关闭球场、生产线搬迁 |",
        "【哪些事项属于重组】\n记忆口诀：",
        "【哪些事项属于重组】\n```text\n卖业务，调结构；\n关场所，搬地区。\n```",
        "【重组义务什么时候确认】\n确认重组义务，关键看企业是否已经承担现时义务。",
        "【重组义务什么时候确认】\n通常需要同时具备：",
        "【重组义务什么时候确认】\n1. 有详细、正式的重组计划；\n2. 该计划已经对外公告或开始实施；\n3. 企业已经使相关各方形成合理预期，表明企业不能单方面撤回。",
