        "【保证类质量保证的特殊列报】\n对于期限在一年或一个营业周期以上的保证类质量保证形成的预计负债，应当根据预计清偿时间拆分列报。",
        "【保证类质量保证的特殊列报】\n如果企业能够合理预计未来一年或一个营业周期以内清偿的金额：",
