        "常见情形如下：",
        "| 财务报告类型 | 资产负债表日 |\n| --- | --- |\n| 年报 | 12 月 31 日 |\n| 半年报 | 6 月 30 日 |\n| 一季报 | 3 月 31 日 |\n| 三季报 | 9 月 30 日 |\n| 月报 | 每月月末 |",
        "季报本身不是资产负债表日，季报的期末日才是资产负债表日。",
        "资产负债表日后事项，是指资产负债表日至财务报告批准报出日之间发生的有利或不利事项。"
