      "topic": "资产负债表日后事项",
      "difficulty": "高频综合",
      "question": "资产负债表日后发现差错是否都要更正",
      "summary": "资产负债表日后至财务报告批准报出日前，如果发现报告年度或以前期间存在会计差错，应当作为资产负债表日后调整事项处理。",
      "conclusion": [
        "资产负债表日后至财务报告批准报出日前，如果发现报告年度或以前期间存在会计差错，应当作为资产负债表日后调整事项处理。",
        "不能简单理解为：",
        "```text\n不重大差错 = 可以不更正\n```",
        "更准确的判断是：",
        "```text\n报出前发现报告年度差错：应调整报告年度财务报表；\n报出后发现以前年度不重要差错：通常计入发现当期相关项目；\n报出后发现重要前期差错：通常追溯重述。\n```"
      ],
      "reasoning": [
        "【判断逻辑】\n资产负债表日后调整事项的前提是财务报告尚未批准报出。",
        "【判断逻辑】\n既然报告还没有正式报出，资产负债表日后发现的差错如果影响报告年度财务报表，就应当在报出前把报告年度报表改正确。",
        "【红字重点】\n<span class=\"text-danger\">虽然金额不重大，但只要是在财务报告批准报出日前发现的报告年度会计差错，报告还没报出，能改就要改，所以应调整报告年度财务报表。</span>",
        "【判断逻辑】\n此时重点不是“重大不重大”，而是：",
        "【判断逻辑】\n```text\n差错是否属于资产负债表日已经存在的情况；\n财务报告是否尚未批准报出。\n```",
        "【判断逻辑】\n如果答案都是“是”，就应作为日后调整事项调整报告年度财务报表。",
        "【和前期差错更正的区别】\n| 情形 | 处理 |\n| --- | --- |\n| 资产负债表日后至财务报告批准报出日前，发现报告年度差错 | 作为日后调整事项，调整报告年度财务报表 |\n| 财务报告批准报出后，发现以前年度不重要差错 | 通常不追溯重述，直接计入发现当期相关项目 |\n| 财务报告批准报出后，发现重要前期差错 | 采用追溯重述法更正 |"
      ],
      "memory": [
        "```text\n报出前发现错，调报告年度；\n报出后小错，进发现当期；\n报出后大错，追溯重述。\n\n不重大，不等于不更正；\n只是可能不用追溯重述。\n```"
      ],
      "pitfalls": [
        "不要把“非重大差错通常不追溯重述”误记成“非重大差错可以不改”。",
        "“不追溯重述”主要是针对财务报告已经批准报出后发现的不重要前期差错。",
        "如果财务报告还没有批准报出，在日后事项期间发现报告年度差错，应当调整报告年度财务报表。"
      ],
      "tags": [
        "资产负债表日后事项"
      ]
