      "question": "资产组减值选择题易错点怎么理解？",
      "summary": "关于资产组减值的表述，正确选项为：",
      "conclusion": [
        "关于资产组减值的表述，正确选项为：",
        "A、D、E、G",
        "| 选项 | 判断 | 核心理由 |",
        "| A | 正确 | 认定资产组最关键的因素是资产组能否独立产生现金流入 |"
      ],
      "reasoning": [
        "### 题目结论\n\n关于资产组减值的表述，正确选项为：\n\n```text\nA、D、E、G\n```\n\n### 选项判断\n\n| 选项 | 判断 | 核心理由 |\n| --- | --- | --- |\n| A | 正确 | 认定资产组最关键的因素是资产组能否独立产生现金流入 |\n| B | 错误 | 即使产品仅供内部使用，只要存在活跃市场，也可能说明该组合能独立产生现金流入 |\n| C | 错误 | 顺序反了。应先以单项资产为基础估计可收回金额；难以估计单项资产可收回金额时，再以资产组为基础 |\n| D | 正确 | 认定资产组时，应考虑管理层对生产经营活动的管理方式，以及对资产使用、处置是否一体化决策 |\n| E | 正确 | 如果资产组可收回金额口径不包括已确认负债，则资产组账面价值中也应扣除该负债，保持口径一致 |\n| F | 错误 | 资产组减值先冲减商誉，再按比例分摊给其他适用资产，不是直接分摊给资产组中所有资产 |\n| G | 正确 | 分摊减值后，单项资产账面价值不得低于三者最高者 |\n\n### E 选项重点\n\nE 选项容易误判。\n\n它的核心不是“所有负债都要扣”，而是：\n\n```text\n可收回金额和账面价值的比较口径要一致。\n```\n\n如果资产组可收回金额没有包括某项已确认负债，资产组账面价值中也应扣除该负债。\n\n### F 选项重点\n\n资产组减值损失不是分摊给资产组中的所有资产。\n\n正确顺序是：\n\n1. 先抵减商誉；\n2. 剩余减值再按账面价值比例分摊给其他适用资产；\n3. 存货、金融资产等适用其他准则的资产，通常不参与资产减值准则下的资产组减值分摊；\n4. 单项资产还要受减值底线限制。\n\n### 记忆口诀\n\n资产组认定看独立现金流，也看管理层一体化决策。\n\n账面价值和可收回金额，口径必须一致。\n\n资产组减值先商誉，后资产；不是所有资产都能分。"
      ],
