      "id": "non-monetary-exchange-monetary-assets-prepayment",
      "updatedAt": "2026-07-01",
      "topic": "非货币性资产交换",
      "difficulty": "高频基础",
      "question": "货币性资产怎么判断，为什么预付账款不算？",
      "summary": "货币性资产的关键不是科目名称，而是未来是否以固定或可确定金额收取货币资金。预付账款通常收回的是商品、服务或其他资产，所以不是货币性资产。",
      "conclusion": [
        "货币性资产不是只限于现金、银行存款、应收账款、应收票据和债权投资。",
        "判断标准是未来是否能够以固定或可确定金额收取货币资金。",
        "预付账款通常代表未来取得商品、服务或其他非货币性资产的权利，因此不属于货币性资产。"
      ],
      "reasoning": [
        "### 核心结论\n\n货币性资产不是只限于现金、银行存款、应收账款、应收票据和债权投资这几类。\n\n判断货币性资产的关键是：企业未来是否能够以固定或可确定金额收取货币资金。\n\n常见货币性资产包括：\n\n```text\n现金\n银行存款\n应收账款\n应收票据\n其他应收款\n债权投资等\n```\n\n### 判断逻辑\n\n判断一项资产是否属于货币性资产，不看科目名称本身，而看未来收回的内容。\n\n```text\n未来收回固定或可确定金额的钱：货币性资产\n未来收回商品、服务、固定资产、存货等非货币性资源：非货币性资产\n```\n\n所以，应收账款、应收票据、债权投资等属于货币性资产，是因为它们代表企业未来收取固定或可确定金额现金的权利。\n\n预付账款不属于货币性资产，是因为它通常代表企业未来取得商品、接受服务或取得其他非货币性资产的权利，而不是未来收取现金的权利。\n\n例如，企业预付 100 万元采购材料：\n\n```text\n借：预付账款 100\n    贷：银行存款 100\n```\n\n这时企业未来通常不是收回 100 万元现金，而是取得材料。因此，预付账款不符合“以固定或可确定金额收取货币资金”的特征。",
        "### 对比理解\n\n| 项目 | 未来收回内容 | 是否属于货币性资产 | 理由 |\n| --- | --- | --- | --- |\n| 应收账款 | 固定或可确定金额的钱 | 是 | 未来收钱 |\n| 应收票据 | 固定或可确定金额的钱 | 是 | 未来收钱 |\n| 其他应收款 | 固定或可确定金额的钱 | 是 | 未来收钱 |\n| 债权投资 | 本金、利息等现金流 | 是 | 未来收取可确定现金流 |\n| 预付账款 | 商品、服务或其他资产 | 否 | 未来收货或接受服务，不是收钱 |"
      ],
      "memory": [
        "应收是收钱，预付是收货。",
        "收钱是货币性资产，收货不是。"
      ],
      "pitfalls": [
        "不要把“金额确定”误解成货币性资产。",
        "预付账款虽然账面金额通常是确定的，但它代表的不是未来收取现金。",
        "判断重点不是账面上有多少钱，而是未来拿回来的是什么。"
      ],
      "tags": [
        "非货币性资产交换",
        "货币性资产",
        "预付账款",
        "应收账款",
        "Markdown同步"
      ]
