        "### 对比理解\n\n| 情形 | 计量基础 | 原因 |\n| --- | --- | --- |\n| 有商业实质，且换入或换出资产至少一方公允价值能够可靠计量 | 公允价值计量 | 交易真实改变经济利益，金额也能可靠确定 |\n| 无商业实质 | 账面价值计量 | 不确认交换损益 |\n| 有商业实质，但换入和换出资产公允价值均不能可靠计量 | 账面价值计量 | 金额不能可靠确定 |",
        "### 举例理解\n\n企业以一台设备换入一项无形资产：\n\n```text\n换出设备账面价值：80 万元\n换出设备公允价值：100 万元\n换入无形资产公允价值：不能可靠计量\n该交换具有商业实质\n```\n\n这种情况下，虽然换入无形资产的公允价值不能可靠计量，但换出设备的公允价值能够可靠计量，并且交换具有商业实质，因此仍然可以按公允价值计量。\n\n不能因为换入资产没有公允价值，就直接退回账面价值计量。"
