      "id": "non-monetary-exchange-multiple-assets-allocation",
      "updatedAt": "2026-07-01",
      "topic": "非货币性资产交换",
      "difficulty": "高频提高",
      "question": "同时换入或换出多项资产时，入账金额和处置损益怎么分摊？",
      "summary": "换入多项资产时，先定可分摊总额，再按公允价值比例分摊；公允价值不能可靠计量时，按账面价值比例或其他合理比例分摊。换出多项资产时，公允价值计量下分项确认损益，账面价值计量下不确认损益。",
      "conclusion": [
        "换入多项资产：先确定换入资产总成本，再分摊给各项换入资产。",
        "以公允价值为基础计量时，通常按各项换入资产公允价值的相对比例分摊。",
        "以账面价值为基础计量时，优先按换入资产公允价值比例分摊；公允价值不可靠时，按原账面价值比例或其他合理比例分摊。",
        "换出多项资产时，公允价值计量下分别确认各项处置损益；账面价值计量下不确认损益。"
      ],
      "reasoning": [
        "### 换入多项资产的分摊\n\n```text\n某项换入资产入账金额\n= 可分摊的换入资产总成本 × 该项换入资产公允价值 / 各项换入资产公允价值总额\n```\n\n如果换入资产中包含金融资产，金融资产通常按金融工具准则确认和计量，不参与非金融资产成本分摊。剩余金额再分摊给其他换入资产。",
        "### 账面价值计量下的分摊顺序\n\n如果采用账面价值计量，先按换出资产账面价值、补价、增值税和相关税费确定换入资产总成本，再分摊给各项换入资产。\n\n```text\n优先按各项换入资产公允价值比例分摊；\n如果公允价值不能可靠计量，按各项换入资产原账面价值比例或其他合理比例分摊。\n```",
        "### 换出多项资产的处置损益\n\n如果以公允价值为基础计量，同时换出多项资产，应按各项换出资产的公允价值与账面价值之间的差额分别确认损益。\n\n```text\n某项换出资产处置损益\n= 该项换出资产公允价值 - 该项换出资产账面价值\n```\n\n如果以账面价值为基础计量，则不确认各项换出资产处置损益。"
      ],
      "memory": [
        "换入多项，先定总额再分摊。",
        "换出多项，公允计量分项认损益。",
        "账面计量，一律不认交换损益。"
      ],
      "pitfalls": [
        "不要把多项资产交换只看成一个总数。",
        "换入多项资产时要分摊入账金额。",
        "换出多项资产时，如果是公允价值计量，要分别确认各项换出资产损益。"
      ],
