      "question": "合同成立五个条件如何快速记忆？",
      "summary": "收入准则下合同成立抓“批、权、款、商、收”：批准承诺、权利明确、付款条款明确、具有商业实质、对价很可能收回。",
      "conclusion": [
        "合同成立是收入确认的前提。",
        "五条件：各方已批准并承诺履约；合同明确各方权利；合同有明确付款条款；合同具有商业实质；企业因转让商品有权取得的对价很可能收回。"
      ],
      "reasoning": [
        "“批”解决合同是否真正成立；“权”解决交付什么、谁享有权利；“款”解决对价怎么收；“商”解决交易是否改变现金流风险、时间或金额；“收”解决客户支付能力和意图。",
        "即使客户取得了实物或控制权，如果合同不满足成立条件，通常不能按收入准则正常确认收入。"
      ],
      "memory": [
        "口诀：批、权、款、商、收。",
        "批：批准承诺；权：权利明确；款：付款明确；商：商业实质；收：很可能收回。"
      ],
      "pitfalls": [
        "不要只看是否交付商品；合同成立条件不满足时，收入确认基础不成立。",
        "“很可能收回”关注客户支付能力和支付意图。"
      ],
      "tags": [
        "收入准则",
        "Markdown同步",
        "合同成立",
        "批权款商收"
      ]
