      "topic": "收入准则",
      "difficulty": "高频易错",
      "question": "合同合并和单项履约义务合并有什么区别？",
      "summary": "合同合并解决“几份合同当一份看”，履约义务识别解决“一份合同里有几项义务”。合并合同后仍可能有多项履约义务。",
      "conclusion": [
        "合同合并发生在合同层面，判断多份合同是否应作为一份合同处理。",
        "单项履约义务识别发生在合同内部，判断承诺商品或服务是否可明确区分。",
        "两份合同合并后，仍可能包含多项单项履约义务。",
        "同一客户（或其关联方）在同时或相近时间订立多份合同，满足同一商业目的一揽子交易、对价相互依赖、承诺构成单项履约义务任一条件时，应合并处理。"
      ],
      "reasoning": [
        "例如同一商业目的、对价相互关联、商品构成一项单一履约义务的多份合同，可能需要合并。",
        "合并后仍要继续识别履约义务：例如销售电脑和提供后续维护服务，电脑与维护可明确区分时，仍是两项履约义务。",
        "合同层面的合并不等于履约义务层面的合并。"
      ],
      "memory": [
        "合同合并：几份合同当一份。",
        "履约义务识别：一份合同拆几项。",
        "先合合同，再拆义务。"
      ],
      "pitfalls": [
        "不要以为合同合并后只能有一项履约义务。",
        "不要把“同一客户、同一时间签订”直接等同于合同合并，仍要看商业目的和对价关联。"
      ],
      "tags": [
        "收入准则",
        "Markdown同步",
        "合同合并",
        "履约义务识别"
      ]
