      "id": "revenue-transaction-price-significant-financing",
      "updatedAt": "2026-07-07",
      "topic": "收入准则",
      "difficulty": "高频易错",
      "question": "重大融资成分怎么判断和做分录？",
      "summary": "重大融资成分本质是商品转让和收付款存在时间差，且差额主要是融资利益。交易价格按现销价格确定，差额按实际利率法确认为利息收入或利息支出。",
      "conclusion": [
        "若合同存在重大融资成分，交易价格按假定客户取得商品控制权时即以现金支付的金额确定。",
        "合同价款与现销价格的差额，在合同期间内采用实际利率法摊销。",
        "企业只有确认合同资产或应收款项、合同负债时，才分别确认重大融资成分相关利息收入或利息支出。"
      ],
      "reasoning": [
        "间隔不超过一年，可不考虑重大融资成分。",
        "预付款且客户可自行决定商品转让时间、对价取决于未来事项、差额由保护性条款或政府审批流程等其他原因导致，通常不属于融资成分。",
        "客户先付款形成合同负债，企业可能确认利息支出；客户后付款形成应收款或合同资产，企业可能确认利息收入。"
      ],
      "memory": [
        "现销价定收入，差额算利息。",
        "一年内可简化；保护性差额不是融资。"
      ],
      "pitfalls": [
        "不要按合同名义总额直接确认收入。",
        "不要在尚未确认合同资产、应收款项或合同负债时确认利息影响。"
      ],
      "journalEntries": [
        {
          "title": "客户延期付款存在重大融资成分",
          "scope": "收入确认",
          "condition": "现销价格低于合同收款总额",
          "lines": [
            {
              "side": "借",
              "account": "长期应收款",
              "amount": "合同收款总额"
            },
            {
              "side": "贷",
              "account": "主营业务收入",
              "amount": "现销价格"
            },
            {
              "side": "贷",
              "account": "未实现融资收益",
              "amount": "差额"
            }
          ],
          "note": "后续按实际利率法确认利息收入。"
        }
      ],
