      "question": "企业集团内成员单位的联营企业之间，是否自动构成关联方？",
      "summary": "企业集团以控制关系圈定，母公司和子公司属于集团成员；联营企业、合营企业通常在集团外。集团成员与集团内其他成员单位的联营企业可以构成关联方，但两个集团外联营企业之间不因分别受集团成员重大影响而自动构成关联方。",
