        "【认股权证、期权：库存股法】假定所有权证行权，企业收到行权资金后，按适用期间的平均市价回购普通股；两者的差额才是增量普通股。<span class=\"text-danger\">如果权证或期权在本期新发行，平均市价只取“发行日到期末”的平均市价；其潜在普通股数量也只按发行日起的期间加权。</span>若 6,000 万份权证行权价为 8 元、平均市价为 10 元：\n```text\n增量普通股＝6,000－6,000×8÷10＝1,200（万股）\n```\n行权价低于市价，低价行权会产生增量股数，具有稀释性。",
