      "summary": "需要重算各列报期间 EPS 的典型事项包括无对价改变股数的股票股利、转增股本、拆股并股，含送股因素的低价配股，同一控制下企业合并对价股份，以及导致以前年度损益追溯调整或追溯重述的事项。普通有偿定向发行和当期差错更正通常不要求重算以前各列报期间 EPS。",
