        "固定换固定判断：行权价固定为 30 元/股，股数固定为 10 万股，结算方式是收现金并交付固定数量自身普通股，因此满足固定换固定。",
        "初始确认：期权公允价值 90 万元，甲公司收到期权费时，借记银行存款 90，贷记其他权益工具 90。",
        "期末公允价值变为 100 万元，只是市场价值变化；因为该合同已经分类为发行方权益工具，不确认 10 万元公允价值变动损失。",
