      "summary": "债权人换入非金融资产时，先以放弃债权的公允价值作为资产成本基础；税费、运杂费、安装费等并不统一计入债务重组损益，而应按换入资产自身准则判断是否资本化。可抵扣进项税额单独核算，不计入资产成本。",
